pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(address actor, uint256 amount) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(this));
        vm.assume(actor != msg.sender); // msg.sender (test contract) is the owner of c
        amount = bound(amount, 1, 100 ether);

        // fund c with the fuzzed amount via fallback
        vm.deal(address(this), amount);
        (bool sent, ) = address(c).call{value: amount}("");
        assertTrue(sent, "funding failed");
        assert(address(c).balance == amount);

        // a non-owner tries to withdraw everything
        vm.prank(actor);
        try c.withdrawAll() {
            // If a non-owner call succeeds, it must not change the balance is impossible here:
            // the reference reverts, so reaching this block already means a non-owner withdrew.
            assertTrue(false, "non-owner withdrew all funds");
        } catch {
            assertTrue(address(c).balance == amount, "balance changed on failed withdrawAll");
        }
    }
}

